package workshop.vfx.paper.m8;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.m8.K1Fixture.*;
import workshop.vfx.delivery.*;
import workshop.vfx.math.core.*;
import workshop.vfx.scene.*;

/** All twelve original K1 case identifiers retained (historical method names), with authorized visual-specific formulas updated for K1.2. */
class K1GeometryTest {
    @Test void exactTierTotalsAndReservations(){int[] n={20,34,44};for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);var d=f.draft(A);assertEquals(n[tier.ordinal()],frame(d).pointCount());assertEquals(n[tier.ordinal()],d.recipe().variant(tier).maxPointsPerFrame());}}
    @Test void paletteAndRolesAreExact(){var r=AuraRecipe.create(1200);assertEquals(EffectPriority.NORMAL,r.priority());assertEquals(LayerRole.ESSENTIAL,r.role("orbit"));for(String name:new String[]{"stroke-a","stroke-b","halo"})assertEquals(LayerRole.STANDARD,r.role(name));var f=new K1Fixture();f.balanced();for(var b:frame(f.draft(A)).batches())assertEquals(b.layer().equals("halo")?M8StyleCatalog.CYAN_HALO:workshop.vfx.paper.core.DemoStyleCatalog.END_ROD,b.style());}
    @Test void bothLayersMatchIndependentFormulaAtAllTiersAndBoundaryTicks(){
        for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);for(long age:new long[]{0,1,15,30,59,60,79,80,123,1199}){
            f.tick=100+age;double[] p=f.position.get(A);p[0]=0.28*age;p[1]=64+Math.sin(age/5.0);p[2]=-0.1*age;p[3]=(float)(age*3.0);
            for(var b:frame(f.draft(A)).batches())for(int i=0;i<b.size();i++)assertTrue(b.point(i).sub(K12GeometryOracle.world(K12GeometryOracle.local(b,i,age),p)).length()<1e-9,"tier="+tier+" age="+age+" layer="+b.layer()+" i="+i);
        }}
    }
    @Test void waistAndHaloRadiiHeightsAndNoSeamDuplicate(){var f=new K1Fixture();f.balanced();for(var b:frame(f.draft(A)).batches()){for(int i=0;i<b.size();i++){if(b.layer().equals("halo")){assertEquals(0.45,Math.hypot(b.x(i),b.z(i)),1e-12);assertEquals(66.15,b.y(i),1e-12);}else{assertEquals(-.85,b.z(i),1e-12);double radius=Math.hypot(b.x(i),b.y(i)-65.25);if(b.layer().equals("orbit"))assertEquals(1.05,radius,1e-12);else assertTrue(radius<.665*(1.05/.78));}}assertTrue(b.point(0).sub(b.point(b.size()-1)).length()>.1);}}
    @Test void rearSwayAndHaloSpinKeepTheirIndependentPeriods(){var f=new K1Fixture();f.balanced();var zero=frame(f.draft(A));f.tick=120;var quarter=frame(f.draft(A));assertArrayEquals(zero.batches().get(0).coordinates(),quarter.batches().get(0).coordinates());assertTrue(quarter.batches().get(1).point(0).sub(zero.batches().get(1).point(0)).length()>.5);assertTrue(quarter.batches().get(3).z(0)>0);f.tick=180;var repeat=frame(f.draft(A));for(int b=0;b<repeat.batches().size();b++)assertArrayEquals(zero.batches().get(b).coordinates(),repeat.batches().get(b).coordinates(),1e-12);}
    @Test void yawMapsForwardLeftAndUp(){for(float yaw:new float[]{0,45,90,180,270,-90,359.5f,720,-1234.25f}){var f=new K1Fixture();f.position.get(A)[3]=yaw;f.balanced();var q=f.draft(A).anchor().rotation();double r=Math.toRadians(yaw);assertTrue(q.rotate(Vec3.Z).sub(new Vec3(-Math.sin(r),0,Math.cos(r))).length()<1e-12);assertTrue(q.rotate(Vec3.X).sub(new Vec3(Math.cos(r),0,Math.sin(r))).length()<1e-12);assertTrue(q.rotate(Vec3.Y).sub(Vec3.Y).length()<1e-12);}}
    @Test void headYawAndPitchDoNotTiltOrRotateAttachment(){var f=new K1Fixture();f.balanced();var expected=frame(f.draft(A));for(double pitch:new double[]{-90,90,0,Float.NaN}){f.position.get(A)[4]=127;f.position.get(A)[5]=pitch;var actual=frame(f.draft(A));for(int b=0;b<expected.batches().size();b++)assertArrayEquals(expected.batches().get(b).coordinates(),actual.batches().get(b).coordinates());}}
    @Test void walkingSprintingJumpingAndFallingHaveExactCentres(){var f=new K1Fixture();f.balanced();for(int i=0;i<100;i++){f.tick++;double[] p=f.position.get(A);p[0]+=i<50?.22:.28;p[1]=64+2*Math.sin(i/10.0);p[2]+=.1;p[3]=i*7;for(var b:frame(f.draft(A)).batches()){Vec3 actual=Vec3.ZERO,expected=Vec3.ZERO;for(int j=0;j<b.size();j++){actual=actual.add(b.point(j));expected=expected.add(K12GeometryOracle.world(K12GeometryOracle.local(b,j,f.tick-100),p));}assertTrue(actual.mul(1.0/b.size()).sub(expected.mul(1.0/b.size())).length()<1e-10);}}}
    @Test void worldChangeContinuesWithSameRecipeClockAndNoInterpolatedPoints(){var f=new K1Fixture();f.balanced();var first=f.draft(A);f.worlds.put(A,W2);f.position.put(A,new double[]{10000,80,-3000,90,0,0});f.tick=223;var next=f.draft(A);assertEquals(first.requestId(),next.requestId());assertSame(first.recipe(),next.recipe());assertEquals(123,next.frameOrdinal());assertEquals(f.ids.worldId(W2),next.worldId());for(var b:frame(next).batches())for(int i=0;i<b.size();i++){assertTrue(Math.abs(b.x(i)-10000)<=1.901);assertTrue(Math.abs(b.z(i)+3000)<=1.901);assertTrue(b.point(i).sub(K12GeometryOracle.world(K12GeometryOracle.local(b,i,123),f.position.get(A))).length()<1e-9);}}
    @Test void sceneAndShapesAreReusedAcrossFramesOwnersAndReplacement(){var f=new K1Fixture();f.balanced();var one=f.draft(A);f.auras.start(B,QualityTier.HEAVY,f.tick);assertSame(one.recipe(),f.draft(B).recipe());var shape=one.recipe().variant(QualityTier.BALANCED).layers().get(0).shape();for(int i=0;i<60;i++){f.tick++;var d=f.draft(A);assertSame(one.recipe(),d.recipe());assertSame(shape,d.recipe().variant(d.tier()).layers().get(0).shape());}f.start(QualityTier.SIMPLE);assertSame(one.recipe(),f.draft(A).recipe());}
    @Test void deterministicFrameHasNoHiddenClockOrRandomInput(){var f=new K1Fixture();f.balanced();f.tick=321;var a=frame(f.draft(A));var b=frame(f.draft(A));assertEquals(a.localTicks(),b.localTicks());for(int i=0;i<a.batches().size();i++)assertArrayEquals(a.batches().get(i).coordinates(),b.batches().get(i).coordinates());}
    @Test void recipeLifetimeBoundsRejectWithoutClamping(){for(int n:new int[]{-1,0,19,12001,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->AuraRecipe.create(n));assertNotNull(AuraRecipe.create(20));assertNotNull(AuraRecipe.create(12000));}
}
